27	  const root2 = makeRepo({ changed: { 'a.txt': 'x\n' } });
28	  try {
29	    assert.deepEqual(runRule(monitor, buildContext({ root: root2, mode: 'all', transcriptPath: polled.path })).map((f) => f.what), ['a Monitor polling GitHub through the shell: "; do gh "']);
30	  } finally { cleanup(root2); polled.cleanup(); }
31	  // The phrase inside text a command carries — a commit message, a heredoc line
32	  // mid-sentence — is not the command, and the guard must not read it as one.
33	  assert.deepEqual(judge('git-pull-on-shallow-clone', ['git commit -m "never run git pull here"', 'echo "(git pull, merging main)"']), []);
